-- Maverlang — Ondo Stocks como segundo emisor del catálogo (M52b).
-- NO APLICADA todavía: la aplica el operador cuando Manu autorice, DESPUÉS de 0021.
-- Pegar UNA vez en el SQL Editor DESPUÉS de 0021_*.sql.
-- Idempotente: se puede volver a ejecutar (add column if not exists,
-- drop constraint if exists + add constraint, create index if not exists,
-- update sólo de nulos, insert on conflict do nothing).
-- Sin pg_catalog.current_date, sin tocar 0001_init.sql.
-- Todas las filas Ondo entran en `watch`: se ven con "En revisión", no se
-- operan; pasan a `listed` solas por la histéresis de nextSafetyState.

-- 1. Emisor por fila: `xstocks` (Backed) u `ondo` (Ondo Stocks).
alter table public.assets
  add column if not exists issuer text not null default 'xstocks';
alter table public.assets drop constraint if exists assets_issuer_check;
alter table public.assets
  add constraint assets_issuer_check check (issuer in ('xstocks', 'ondo'));

-- 2. Ticker del subyacente, para agrupar una ficha por empresa.
alter table public.assets
  add column if not exists company_ticker text;

create index if not exists assets_company_ticker_idx
  on public.assets (company_ticker);

-- 3. Rellena company_ticker de las filas xStocks existentes (underlying = ticker).
update public.assets
  set company_ticker = underlying
  where company_ticker is null and underlying is not null;

-- 4. Filas Ondo (444): watch, no curadas, contadores en 0.
